export const meta = {
  name: 'x32-mcp-implement',
  description: 'Implement x32-mcp modules against docs/DESIGN.md as a dependency graph, then adversarially review and fix',
  phases: [
    { title: 'Foundations', detail: 'osc, scales, device.yaml, dashboard page' },
    { title: 'Core', detail: 'descriptor, connection, nodes, policy, meters, detector' },
    { title: 'Runtime', detail: 'fakedesk, desk facade' },
    { title: 'Features', detail: 'provision+cfs, patches, webui server' },
    { title: 'Server', detail: 'MCP tools + end-to-end tests' },
    { title: 'Review', detail: 'lens reviewers → dedupe → fixes → full suite' },
  ],
}

const ROOT = 'C:/Users/jim/Documents/claude/x32-mcp'
const PY = `${ROOT}/.venv/Scripts/python`

const COMMON = `
PROJECT: x32-mcp at ${ROOT} (Windows; git repo; Python 3.12 venv at ${ROOT}/.venv). You are one of several agents building it concurrently.
READ FIRST (in this order): ${ROOT}/docs/DESIGN.md (the binding module contract — implement EXACTLY the signatures there), ${ROOT}/docs/BRIEF.md (why), and the research files under ${ROOT}/docs/research/ named in your task (verified protocol ground truth — cite them in code comments where behaviour is non-obvious, e.g. "# per docs/research/meters.md: count is little-endian").
Existing code to reuse: src/x32mcp/config.py, events.py, targets.py (read them; do not modify).
RULES:
- Own ONLY the files listed in your task. Never edit other modules; if you need a change elsewhere, describe it in notes_for_dependents/open_issues instead.
- Pure Python; only deps: mcp 2.x, pyyaml, websockets 17. stdlib asyncio/socket for networking. No numpy. No print() to stdout anywhere in src/x32mcp (stdout is the MCP transport) — use logging.
- Engineering units at public boundaries (dB, Hz, ms, 1-based numbers, enum tokens). Mutes: on-the-wire /mix/on 1 = ON (unmuted).
- Every network wait has a timeout. Never hang.
- Type hints + docstrings stating units/ranges. Match the style of the existing modules (concise, comments only where behaviour is non-obvious).
- Tests: write ${ROOT}/tests/test_<module>.py (or the integration file named in your task) with pytest (asyncio_mode=auto is configured; async def tests just work). Run ONLY your tests with: "${PY}" -m pytest tests/test_<module>.py -q   (from ${ROOT}). Never run "uv sync"/pip. Do not run the whole suite (other agents' files may be mid-write).
- If DESIGN.md conflicts with verified research, follow research and record the deviation. If DESIGN.md is silent, decide sensibly and document in the module docstring.
- Work until your tests pass. Then return the structured output ONLY (no prose).`

const IMPL_SCHEMA = {
  type: 'object',
  properties: {
    files: { type: 'array', items: { type: 'string' }, description: 'files you created/modified' },
    tests_passed: { type: 'boolean' },
    test_summary: { type: 'string', description: 'pytest tail, e.g. "23 passed"' },
    deviations: { type: 'array', items: { type: 'string' }, description: 'where you departed from DESIGN.md and why' },
    notes_for_dependents: { type: 'array', items: { type: 'string' }, description: 'API facts a dependent module MUST know (exact names, arg orders, quirks)' },
    open_issues: { type: 'array', items: { type: 'string' } },
  },
  required: ['files', 'tests_passed', 'test_summary', 'deviations', 'notes_for_dependents', 'open_issues'],
}

const notes = (...results) => {
  const lines = []
  for (const r of results) {
    if (!r) continue
    for (const n of r.notes_for_dependents || []) lines.push(`- ${n}`)
    for (const d of r.deviations || []) lines.push(`- (deviation) ${d}`)
  }
  return lines.length ? `\nNOTES FROM UPSTREAM MODULES (authoritative over DESIGN.md where they differ):\n${lines.join('\n')}\n` : ''
}

const impl = (label, phase, prompt, opts = {}) =>
  agent(`${COMMON}\n\nTASK ${label}:\n${prompt}`, { label, phase, schema: IMPL_SCHEMA, ...opts })

// ---------------------------------------------------------------- Foundations
const A_osc = impl('impl:osc', 'Foundations', `Implement src/x32mcp/osc.py + tests/test_osc.py per DESIGN.md §5. Research: docs/research/transport.md (wire format, missing typetags on requests, blob layout). Golden vectors: build the expected bytes by hand in the test (not via encode) for /info (no args), "/ch/01/mix/fader" ,f 0.75, "/node" ,s "ch/01/config", a ,b blob of 8 bytes, a ,i, a message with several args, and a message with NO typetag string. Fuzz: 500 random byte strings must raise OscError or return an OscMessage, never anything else.`)

const A_scales = impl('impl:scales', 'Foundations', `Implement src/x32mcp/scales.py + tests/test_scales.py per DESIGN.md §6. Research: docs/research/scales_params.md — the fader taper formula there (verified against Maillot's C) is authoritative; if it differs from DESIGN.md §6, follow research and record the deviation. Include: fader_to_db/db_to_fader, quantize, lin/log helpers (log must work with hi<lo as for Q 10→0.3), enum helpers, the Scale dataclass with to_value/to_raw/clamp (kinds: level, lin, log, enum, int, bool, str, pan), format_db (−inf → "-oo", one decimal, explicit + sign for positive). Round-trip tests at −90, −60, −30, −10, 0, +10 dB exactly; monotonic over 1024 steps; pan 0/0.5/1 ↔ −100/0/+100; log freq 0/0.5/1 ↔ 20/632.5/20000 (check the exact midpoint from research); Q inverted; enum index↔token; steps quantisation.`)

const A_yaml = impl('impl:device.yaml', 'Foundations', `Author ${ROOT}/device.yaml — the complete descriptor per the schema in DESIGN.md §7 — plus tests/test_device_yaml.py (a pure-YAML sanity test: loads with pyyaml, top-level keys present, every enum referenced by a param exists, every nodes field references a declared param path, all 100 rta band_hz and 31 geq band_hz present and ascending). Research: docs/research/scales_params.md (params, scales, node line formats & field order, enums, colour table, source table, headamp), docs/research/fx_routing_scenes.md (fx types, GEQ2 par layout, insert enums, routing enums, mute groups, scenes/-show/-action), docs/research/meters.md (rta band frequencies, rta source param + enum, meter types), docs/research/transport.md (node sections & verbatim example lines). Cover: ch (config, preamp, gate incl filter, dyn incl filter, eq 1-4, mix, sends 1-16 odd/even, grp, insert), auxin, fxrtn, bus (config, mix, sends to mtx 1-6, eq 1-6, dyn, insert, grp), mtx, main st/m, dca, headamp (000-127: gain, phantom), fx 1-8 (type, source l/r, par 1-64), config (routing IN/AES50A/AES50B/CARD/OUT blocks, mute 1-6, talk, solo, mon as read-only), -show (prepos/current, showfile/show/name, showfile/scene/000-099 name/notes/hasdata), -stat (selidx, solo, talk, rta/*), -prefs (name, rta/*), -action (goscene, gocue, gosnippet as tier 2 int params). The nodes list must cover every section needed for a faithful snapshot (config/mix/sends/eq/dyn/gate/preamp/insert/grp for all strips, headamp, fx, config/routing, config/mute, -show/prepos, -stat/rta, -prefs/rta). Two fx type enums (fx_type_14 for /fx/1-4 with 61 entries, fx_type_58 for /fx/5-8 where GEQ2 = 0 — see fx_routing_scenes.md §1), insert_sel with 23 entries, fader scale steps 1024 vs send scale steps 161 (scales_params.md §2.3), rta section exactly as DESIGN.md §7 (band_hz computed as 10000*2**((i-90)/10), rounded to 2 decimals). Each param spec: osc (f/i/s), scale name or enum, node format token (vocabulary from DESIGN.md §9; add tokens only if the research shows a format that needs one, and list them in notes_for_dependents), tier, clamp, inverted_mute. Use YAML anchors to avoid repeating ch/auxin/fxrtn parameter blocks (auxin/fxrtn have no preamp gain/gate? — check research; auxin has preamp trim/invert, no gate/dyn? verify). Write the node field ORDER exactly as the desk prints it (from the verbatim example lines). Also put the policy/rta/geq/detector/ringout/mics sections with the values from DESIGN.md §7. Keep comments in the YAML citing research lines for anything surprising. Report the total number of concrete node paths a full sweep would need (compute it in the test and print it in the test output).`)

const A_page = impl('impl:webui-page', 'Foundations', `Write ${ROOT}/webui/index.html — the read-only CFS² dashboard page per DESIGN.md §17 (message schema is fixed there) — plus tests/test_webui_page.py (static checks: file exists, contains no external <script src>/<link href> (fully self-contained, no CDN), contains the WS message types "hello","rta","state","notches","event", handles "?demo=1"). Single file: inline CSS + vanilla JS + <canvas>. Dark theme, high contrast, large type, touch-tolerant (no hover-only info), works on a 768px tablet and a phone (responsive: stack panels). Views: (1) RTA bars, 100 bands, log-frequency x axis with labelled ticks (20, 50, 100, 200, 500, 1k, 2k, 5k, 10k, 20k), dB y axis −90..0, peak-hold line; (2) waterfall spectrogram (2-D heatmap, time scrolls downward, newest row at the top or bottom — choose and label; colour ramp from near-black through blue/magenta to yellow/white; keep ~15 s of history; use an offscreen canvas + drawImage shift for speed); (3) notch markers overlaid on the RTA at each active GEQ cut showing depth (e.g. "−6") and frequency, colour-coded by session_id hash; (4) state panel: mode badge (IDLE/WATCH/RING-OUT/SYSTEM) with colour, bus + name, master dB, budget left, candidate confidence bar (0–1) with freq, stage, connection state + console name + rtt, RTA source; (5) scrolling event log (last 200, newest on top, monospace, timestamps HH:MM:SS.mmm, notch events highlighted). WebSocket to ws://<host>:<port>/ws with reconnect/backoff and a visible "disconnected" banner; decimate rendering with requestAnimationFrame (render the latest frame only). "?demo=1": in-page synthetic source (pink-ish music spectrum with noise, a ring at 2.4 kHz growing +12 dB/s after 3 s, then a simulated notch event at −3/−6 dB that makes it decay, then a second ring at 630 Hz) that exercises every message type without a server — this is the filming/demo mode. Title "CFS² — x32-mcp". Keep it under ~900 lines. No build step.`)

