const A_desc = Promise.all([A_scales, A_yaml]).then(([s, y]) => impl('impl:descriptor', 'Core', `Implement src/x32mcp/descriptor.py + tests/test_descriptor.py per DESIGN.md §7 (Descriptor, ParamSpec, NodeSection, DescriptorError). Load ${ROOT}/device.yaml (already written — read it fully first; do NOT edit it — if it has a defect that blocks you, work around it in the loader and report it in open_issues with the exact fix needed). Use scales.Scale from src/x32mcp/scales.py (already written; read it). Requirements: validation with precise error paths; template params with {n:02d}/{id}/{send:02d}/{band} expansion; param_for_address reverse lookup (compile templates to regexes once); tier_for with fnmatch over guarded globs plus per-param tier; all_node_paths() enumerating every concrete /node path with its ordered ParamSpec list (including odd/even send field lists); strip_targets(); accessors for policy/rta/geq/detector/ringout/mics dicts. Tests: loads real file; counts; reverse lookups incl. sends/eq bands/main/dca/headamp/fx; tier_for("/main/st/mix/fader")==2, ("/ch/05/mix/fader")==1, ("/ch/05/config/name")==1 or per yaml, ("/-action/goscene")==2, ("/config/routing/IN/1-8")==2; every node field resolves to a ParamSpec; encode/decode via ParamSpec.to_raw/to_value for fader, freq, enum, bool, str.${notes(s, y)}`))

const B_conn = A_osc.then(o => impl('impl:connection', 'Core', `Implement src/x32mcp/connection.py + tests/test_connection.py per DESIGN.md §8. Research: docs/research/transport.md (reply-to-source-port, /info & /xinfo reply arg order, /xremote lifetime, /node reply address "node" and payload format, how unknown addresses behave, /renew). Uses osc.py (written; read it) and events.EventBus, config not needed. The Descriptor is passed in but you may only use d.policy.get("read_cache_ttl_s", 2.0) from it — write the class so tests can pass a minimal stub object with a .policy dict (do not import descriptor.py; it may not exist yet). Single asyncio DatagramProtocol bound once; request/reply futures keyed by reply address (node replies keyed by the payload's first token); retries; heartbeat /xremote every 8 s; watchdog → DEGRADED → backoff reconnect; set() refuses when DEGRADED; on_update/on_blob callbacks; get_cached with TTL; node_many with bounded concurrency; slash(line) per DESIGN.md §8 (send address "/" with one string arg, await the desk's echo of the "/" message as the ack — FIFO futures keyed on "/"); discover() broadcasting /xinfo (SO_BROADCAST, temp socket, also unicast 127.0.0.1) collecting replies for timeout_s. Tests use an in-test asyncio UDP responder (write it in the test file) that: answers /info with ,ssss; echoes get requests with a value; answers /node with a canned line; can drop the next N packets; can go silent; sends a blob and a pushed update. Assert: replies arrive on the same local port we sent from (the responder records the source port and the test checks conn's transport port); timeout raises RequestTimeout within ~1.6 s for 3 attempts of 0.5 s (use shorter timeouts in tests via constructor args); degraded detection + reconnect when the responder comes back; blob routed to on_blob only and never crashes decode; node_many returns None for a missing path without raising; slash() resolves when the responder echoes the "/" datagram back and raises RequestTimeout when it does not. Mark tests that need real sockets normally — they bind 127.0.0.1 port 0.${notes(o)}`))

const B_nodes = A_desc.then(d => impl('impl:nodes', 'Core', `Implement src/x32mcp/nodes.py + tests/test_nodes.py per DESIGN.md §9. Research: docs/research/transport.md (verbatim /node reply lines — use them as golden test inputs) and docs/research/scales_params.md (node number formats: dB "-oo"/"-12.0", frequencies "124.7"/"1k00"/"10k0", gains "+0.00", Q "2.0", ints, "+0" pans, ON/OFF, enum tokens, quoted strings with spaces, percentages, any others). Uses descriptor.py (written; read it and the NODE format tokens actually used in device.yaml — grep "node:" in device.yaml to get the full set; implement a parser+renderer for each). dump_desk_state must take any object with "async node_many(paths, concurrency)" (duck-typed; do not import connection.py) and use d.all_node_paths(); it must finish even when some paths return None (recorded in DeskState.missing). DeskState JSON must round-trip -inf as "-oo". SnapshotStore: ids "YYYYMMDD-HHMMSS[-slug]", list newest first, load by unique prefix or "latest". diff_states + describe_changes: English per DESIGN.md (use targets.Target.label for strip names, include the channel name from the state's config section, e.g. "Ch 5 'Vox Tony' fader −4.2 dB → −1.0 dB"; sends "Bus 3 send from Ch 2 −20.0 dB → −17.0 dB (+3.0 dB)"; mutes "Ch 5 'Vox' muted → unmuted"; EQ "Ch 5 EQ band 2 gain +0.0 dB → −3.0 dB"). restore_plan returns node-style write LINES (strings, DESIGN.md §9 — rendered with render_node_line from the snapshot's values) for every differing section, skipping -show/-stat/-prefs/-action sections; parsing must be tolerant per the 'Parsing tolerance' paragraph in §9 (missing trailing tokens → None, extra tokens ignored, adaptive numeric precision, padded columns). Tests: parse/render round-trip for EVERY node section in device.yaml using synthetic values (iterate d.all_node_paths()); verbatim research lines parse to expected dicts; render matches the verbatim line formatting for at least 5 of them (whitespace-normalised if the desk pads columns — document); diff/describe on a scripted change set yields the exact strings above; snapshot store behaviour with tmp_path; dump with a stub node_many.${notes(d)}`))

const B_policy = A_desc.then(d => impl('impl:policy', 'Core', `Implement src/x32mcp/policy.py + tests/test_policy.py per DESIGN.md §10. Uses descriptor.py (written; read it — policy values come from d.policy and d.detector/d.ringout) and events. Implement Tier, PolicyError(code, message), Clamped, PendingConfirmation, Policy with: tier_for, clamp_level (family ceilings: ch/auxin/fxrtn → ch_fader_max_db; bus → bus_fader_max_db; main → main_fader_max_db; dca → ch ceiling; kind="send" → send_max_db; floor −90 → −inf allowed), check_relative (6 dB / 3 dB in show mode / force bypasses), clamp_eq_gain, require_confirmation/consume_token/guard (secrets.token_urlsafe, TTL via injectable clock, single-use, deleted on any outcome; guard() also stores the expected action and rejects a token minted for a different action), check_show_mode_allows, async acquire_write (token bucket writes_per_second, capacity = writes_per_second; if the wait would exceed 1.0 s raise RATE_LIMITED; panic=True bypasses), validate_notch (cuts only; new_db ≤ current_db; new_db ≥ notch_max_db (i.e. not deeper than −9); raise BOOST_FORBIDDEN if new_db > current_db or new_db > 0), ramp_steps(from_db, to_db, ramp_ms) (list of dB values ending exactly at to_db; step every ramp_step_ms; ramp_ms None→default; 0 or |Δ|<0.05 → [to_db]; treat −inf endpoints as −90 for interpolation but return −inf as the final value when to_db is −inf), snapshot_before_write flag + mark_snapshot_taken(). Tests as in DESIGN.md §10 incl. rate limiter timing with a fake clock (make the bucket use an injectable monotonic clock and asyncio.sleep — test with small budgets), tokens, show mode, notch validation, ramp step counts (300 ms / 20 ms → 15 steps).${notes(d)}`))

const B_meters = Promise.all([A_osc, A_desc]).then(([o, d]) => impl('impl:meters', 'Core', `Implement src/x32mcp/meters.py + tests/test_meters.py per DESIGN.md §11. Research: docs/research/meters.md is AUTHORITATIVE for the blob layout (endianness of count and values, the /meters/15 RTA packing, the request arguments incl. any extra ints for /meters/15, subscription lifetime and renewal, RTA source parameters). Read it fully and implement exactly that, with a comment citing it at each layout decision. Uses osc.py, descriptor.py (for rta config: meter_type, bands, band_hz, source param/enum), events. LiveMeters must work with any object having "on_blob(cb)->unsub" and "async send_raw(address, *args, typetags=None)" (duck-typed; do not import connection.py). SyntheticRta: deterministic (seeded random), 100 bands, base "music" spectrum (pink-ish slope, −25 dB at 100 Hz falling to −55 dB at 10 kHz, ±3 dB noise per frame, slow 0.5 Hz wobble), inject_ring(freq_hz, growth_db_per_s, start_db=-45, cap_db=-3) (level grows linearly per frame; the ring energy also leaks ±1 band at −10 dB), inject_note(freq_hz, level_db) (rises fast over ~5 frames then plateaus, i.e. what a held guitar note looks like), attenuate(band_idx, db) / set_geq_gain(hz, db) (a cut at the ring band reduces the ring's effective loop gain: implement as level -= cut applied per frame so the ring decays when cut ≥ its growth margin — document the model), stop_ring(freq_hz), and a "frames()" generator plus the FrameSource start/stop/subscribe API driven by asyncio with period_s (realtime) or a manual tick() for tests. FixtureSource replays lists. average_frames. set_rta_source(conn, d, target, post_eq) writing the exact addresses from research. Tests: hand-built blob byte vectors per research (incl. the packed RTA form if that is what research says) decode to expected values; a blob with a wrong length raises MeterParseError; FixtureSource replay non-realtime; SyntheticRta ring grows ~linearly (fit slope within 20% of requested) and note plateaus; attenuate makes the ring decay.${notes(o, d)}`))

const B_detector = A_desc.then(d => impl('impl:detector', 'Core', `Implement src/x32mcp/detector.py + tests/test_detector.py per DESIGN.md §12 (pure Python, no asyncio, no I/O, no numpy; statistics.median is fine). DetectorConfig.from_descriptor(d) reads d.detector. Implement the heuristic exactly as specified (prominence over the median of ±k neighbours, persistence with ±band_tolerance drift, least-squares slope in dB/s, monotonic tolerance, weighted confidence, cooldown per band after emitting). Also NotchController with band_for_freq (nearest GEQ band in log-frequency), plan() (merge into an adjacent existing notch within merge_adjacent_bands, deepen by notch_step_db to notch_max_db, budget = distinct notched bands), GeqWriter protocol + RecordingGeqWriter. Build the synthetic RTA streams INSIDE the test file with a small deterministic generator (do not depend on meters.py which is being written concurrently): 100 bands with centres per d.rta["band_hz"], frame period 0.05 s: (a) clean music 200 frames → 0 detections; (b) held note at 330 Hz: rises to +20 dB above neighbours over 5 frames then plateaus for 100 frames → 0 detections; (c) ring at 2.4 kHz growing +15 dB/s from −40 dB → detection within 6 frames after prominence first ≥ 12 dB, band within ±1 of the 2.4 kHz band; (d) two rings (2.4 kHz and 630 Hz) → both detected; (e) noise robustness: (c) with ±2 dB random noise still detects; notch controller sequence −3/−6/−9 then None; adjacent merge; budget exhaustion; policy_validate rejecting boosts propagates. Print the frame index of each detection in the test for the record.${notes(d)}`))

// ---------------------------------------------------------------- Runtime
const C_fakedesk = Promise.all([B_conn, B_nodes, B_meters]).then(([c, n, m]) => impl('impl:fakedesk', 'Runtime', `Implement src/x32mcp/fakedesk.py + tests/integration/conftest.py + tests/integration/test_fakedesk.py per DESIGN.md §18. Research: docs/research/transport.md (reply forms for /info /xinfo /status /node, unknown address behaviour, /xremote push format), docs/research/meters.md (exact blob layout to EMIT), docs/research/fx_routing_scenes.md (/-action/goscene, /save, /load, scene names). Uses osc.py, descriptor.py, nodes.render_node_line, meters.SyntheticRta + the blob layout (build blobs the same way meters.parse_meter_blob expects — read meters.py), targets. Initial state: every ParamSpec in the descriptor gets a sensible default raw value (names "Ch01".., colours cycling, faders: ch 0.75 (0 dB), bus 0.75, main 0.75, sends 0.0, eq flat PEQ at 100/1k/4k/10k gains 0 → raw per scale, dyn/gate off, insert OFF, fx types: 1-4 HALL/DLY/CRS/RPLT-ish, 5-8 GEQ2? NO — leave 5-8 as e.g. 'FLNG' etc. so provisioning has work to do, but make fx type settable; headamp gains 0.5-ish, phantom 0; scenes 0-3 named "Init","The Molecules","GravelAxe","Empty" with hasdata for 0-2). Writes: quantise faders to 1023 steps and other float params to their scale steps like the real desk. "/" node-style write (DESIGN.md §18 + transport.md §6.6): parse the string with nodes.parse_node_line against the section's fields (leading slash optional; partial trailing lists allowed), store via ParamSpec.to_raw, echo the received datagram back verbatim to the sender, push changed leaves to xremote clients. /xremote: register sender for 10 s; pushed updates go to other registered clients (and, per research, also/not to the writer — follow research). /meters: subscribe with type + optional args, stream every 50 ms for 10 s, /renew extends; the RTA source follows the desk's rta source params so SyntheticRta reflects "which bus"; closed loop: the ring is attenuated by the GEQ gain (from state) of the FX slot inserted (insert/sel) on the RTA-source bus at the ring band. Control addresses for tests: "/-fake/ring ,f hz" start ring, "/-fake/ring/stop ,f hz", "/-fake/note ,ff hz db", "/-fake/drop ,i n", "/-fake/silence ,i 0|1", "/-fake/latency ,i ms". Provide "python -m x32mcp.fakedesk --port 10023 --name X32-FAKE" (argparse; logs to stderr). conftest.py: session-scoped-per-test fixtures "fakedesk" (FakeDesk started on 127.0.0.1 port 0, yields it), "conn" (X32Connection connected to it, short timeouts), "descriptor". Tests: connect/info/xinfo (incl. discover() via unicast 127.0.0.1); get/set round trip incl. fader quantisation; node line for EVERY concrete node path parses via nodes.parse_node_line with zero errors; full dump_desk_state has missing == [] and takes < 5 s (print the time); xremote push arrives at a second connection; meters frames decode via meters.parse_meter_blob; goscene/save/scene names; drop/silence fault injection leads to RequestTimeout / DEGRADED.${notes(c, n, m)}`))

const C_desk = Promise.all([C_fakedesk, B_policy]).then(([f, p]) => impl('impl:desk', 'Runtime', `Implement src/x32mcp/desk.py + tests/integration/test_desk.py per DESIGN.md §13 (use the fakedesk/conn fixtures from tests/integration/conftest.py — read it). Uses connection, descriptor, nodes, policy, scales, targets, events, meters (only for get_fx GEQ decode if needed). Every read via /node sections (get_strip assembles config+mix+eq+dyn+gate+insert from node lines; cache node lines through conn.get_cached-style TTL — implement a small node cache inside Desk keyed by path with policy read_cache_ttl_s, invalidated on writes to that prefix and on pushed updates). Every write path: policy.tier_for → (Tier 1) policy checks/clamps → ensure_pre_write_snapshot (first write only; label "auto-pre-write") → policy.acquire_write → conn.set → events "write". Ramps: policy.ramp_steps + asyncio.sleep(step) per step, cancel a previous ramp on the same address. Mute inversion lives here. resolve() supports unique case-insensitive channel-name substring matches ("tony" → ch with name "Vox Tony"; ambiguous → DeskError("AMBIGUOUS_NAME") listing candidates). panic(): fire-and-forget mutes on main st/m, bus 1-16, mtx 1-6 with NO ramps and policy.acquire_write(panic=True); return elapsed_ms. Tier-2 executors (set_main_level, set_main_mute, recall_scene, save_scene, restore, set_source, set_phantom, set_insert, set_fx_type, set_geq_band) do not do the confirmation dance (server does) but DO still snapshot-before-write and rate-limit; set_geq_band writes /fx/{slot}/par/{idx} using the GEQ par layout from descriptor (d.geq) and scale. get_fx decodes GEQ bands to dB. Tests against fakedesk: get_channel(1) fields & units; set_fader ch.1 to −6 dB ramp 300 ms → fakedesk received ~15 writes and final raw == db_to_fader(−6) within quantisation; adjust_fader +3; relative > 6 dB without force → error code RELATIVE_TOO_LARGE; force works; clamp to +5 dB reported; mute/unmute inverted correctly on the wire (assert raw /ch/01/mix/on == 0 when muted); sends set/adjust; set_eq_band writes freq/gain/q raw within scale steps; set_pan; set_comp; label; panic elapsed < 200 ms and all 24 mutes applied on the fakedesk; pre-write snapshot created exactly once (tmp snapshot dir); resolve("tony") after labelling; get_sends units; list_scenes/current_scene; recall_scene changes /-show/prepos/current; restore(snapshot) after a change puts the fader back (restore uses nodes.restore_plan lines written via conn.slash — assert the fakedesk received "/" messages, not per-parameter writes); set_geq_band → correct /fx/5/par/NN raw.${notes(f, p)}`))

// ---------------------------------------------------------------- Features
const D_cfs = Promise.all([C_desk, B_detector, B_meters]).then(([dk, det, m]) => impl('impl:provision+cfs', 'Features', `Implement src/x32mcp/provision.py, src/x32mcp/cfs.py, and tests/integration/test_cfs.py per DESIGN.md §14–§15. Research: docs/research/fx_routing_scenes.md (GEQ2 par layout, insert/sel enum, free-slot logic), docs/research/meters.md (RTA source). Uses desk.py, detector.py, meters.py (LiveMeters/FixtureSource/SyntheticRta/set_rta_source), policy, events, nodes (SnapshotStore for the bus-master snapshot), patches (may not exist yet — accept an optional duck-typed patch object with .rows having .channel/.mic/.owner/.monitor_bus; do not import patches.py). provision: validate_ringout_eqs (read-only), plan_setup/apply_setup (idempotent; allocate dual-mono pairs on slots from d.geq["insert_slots_preferred"]; a slot is free iff no strip inserts it AND its type is not already a GEQ that some bus uses; existing GEQ inserts on target buses reused), discover_mics (unmuted + send to bus ≥ floor + physical source (local In / AES50 per source enum) ; plus patch mic flag and mute-group-6 membership from /ch/NN/grp/mute bitmask; discrepancies listed), preflight (blockers: GEQ validation failed, no candidate mics; warnings: master above ringout.start_warn_db, mics disagree between sources). cfs: CfsManager with feedback_watch/stop/ring_out/ring_out_system/abort/state as specified; frames come from an injectable FrameSource (default: LiveMeters on d.rta meter_type via the desk's connection); detector task consumes frames, publishes "cfs.candidate" (throttled to ≤ 5/s) and on Detection uses NotchController + a GeqWriter adapter that calls desk.set_geq_band after policy.validate_notch, publishes "cfs.notch"; ring_out state machine exactly per §15 with events "cfs.stage"; connection DEGRADED (subscribe to events "connection.state") → immediate restore of the starting master via a retry loop + ABORT; ReportStore writes JSON + Markdown summary to settings.report_dir (accept a dir Path); reports include session_id, bus, notches (freq, band, depth, confidence, ts), start/end master dB, gain-before-feedback, abort reason. Tests (integration, fakedesk fixtures; use FixtureSource/SyntheticRta with realtime=False or a fast period and small dwell_ms so the suite stays < 60 s): validate on a fresh fakedesk → not ok (no insert); plan_setup allocates fx slot 5 L/R for buses [1,2]; apply_setup makes validate ok and is idempotent (second apply = no writes); validate reports "insert bypassed" when insert/on is 0 — preflight refuses to arm; discover_mics finds ch 1-2 when they send to bus 1 above −40 dB and are unmuted, excludes a muted one and a card-sourced one; feedback_watch with an injected synthetic ring at 2.4 kHz → a "cfs.notch" event within 1 s, GEQ band 2.5 kHz raw value == −3 dB encoded, ring decays (closed loop) and no boost is ever written (assert every /fx/5/par write ≤ 0 dB); ring_out on bus 1 with target −6 dB from −20 dB: master rises in 1 dB steps (assert monotone writes), notches on detection, ends with master = final − 3 dB safety margin, report file written; abort path: silence the fakedesk mid-ring-out (via /-fake/silence or fakedesk API) → master restored to the starting value once the desk answers again and state ABORT; budget exhaustion path with a ring the GEQ cannot tame (use a ring whose growth exceeds −9 dB max cut) → back off abort_backoff_db and stop; ring_out_system over buses [1,2] produces a consolidated report.${notes(dk, det, m)}`))

const D_patches = C_desk.then(dk => impl('impl:patches', 'Features', `Implement src/x32mcp/patches.py + ${ROOT}/patches/example_band.yaml + ${ROOT}/patches/README.md (schema doc) + tests/test_patches.py (+ an integration test in tests/integration/test_patches.py using the fakedesk/conn fixtures and a Desk — read tests/integration/conftest.py and src/x32mcp/desk.py) per DESIGN.md §16. YAML form: {band: "The Molecules", venue: "…", channels: [{channel: 1, name: "Kick", color: RD, source: "In01", mic: true, owner: "Tony", monitor_bus: 3, notes: "…"}, …]}; CSV form with header channel,name,color,source,mic,owner,monitor_bus,notes (mic accepts true/false/yes/no/1/0/x; blank = unknown/None). Validate: channel 1-32 unique, colour token in the descriptor colour enum (accept lowercase and a few friendly aliases: red/green/yellow/blue/magenta/cyan/white/off → RD/GN/YE/BL/MG/CY/WH/OFF), monitor_bus 1-16. apply_patch_plan labels (name/colour) via desk.label; source only when include_source=True via desk.set_source. export_patch_plan reads names/colours/sources from the desk and merges mic/owner/monitor_bus/notes from merge_with. The example file: a plausible 16-channel band patch (kick, snare top, hats, toms, OH L/R, bass DI, gtr L/R cab mics, keys L/R, vox lead, vox bv 1-2, talkback) with mic flags, owners (use first names only), monitor buses 1-6 — fictional, no real venue. Tests: load yaml + csv equivalence; validation errors; apply writes the right names/colours to the fakedesk; export round-trips.${notes(dk)}`))

const D_webui = Promise.all([B_meters, A_page]).then(([m, p]) => impl('impl:webui-server', 'Features', `Implement src/x32mcp/webui.py + tests/test_webui.py per DESIGN.md §17. Use websockets 17 (installed): websockets.asyncio.server.serve(handler, host, port, process_request=...) where process_request(connection, request) returns connection.respond(HTTPStatus.OK, body) with a text/html Content-Type header for GET "/" (read webui/index.html from settings.webui_dir on each request so edits show without restart), JSON for "/healthz", None for "/ws" (upgrade), 404 otherwise — check the installed API with inspect/help if unsure (Response objects: websockets.http11.Response; set headers via response.headers). Inputs: settings (for dirs/host/port), events (EventBus), a state provider (duck-typed object with a "state" attribute that has a .to_dict() or is a dict — the CfsManager; may be None → mode "idle"), a FrameSource (may be None), band_hz, geq_band_hz, and a "connection_status" callable returning a dict (may be None). Push: hello on connect; rta frames decimated to fps (default 20) using the latest frame only; state on change + at 1 Hz; notches list whenever a cfs.notch event fires (derive from the state provider's notches); every non-frame EventBus event as {"t":"event",...}. Inbound WS messages ignored (log at DEBUG). Robust to slow clients (drop frames rather than queue: per-client "latest frame" slot + send loop). start()/stop() idempotent; bind failure → log warning, raise a WebUIError the caller may ignore. Tests: start on 127.0.0.1 port 0 with meters.SyntheticRta as source (fast period) and a fake state provider; fetch "/" with a raw asyncio HTTP GET (stdlib only) → 200 + contains "<canvas"; "/healthz" → JSON; connect a websockets client (websockets.asyncio.client.connect) → receives hello with 100 band_hz and 31 geq_band_hz, then an rta frame with 100 floats, then a state message; publish an event on the bus → received as t=event; publishing 200 frames quickly to a client that doesn't read → server does not raise and other clients still get frames.${notes(m, p)}`))

// ---------------------------------------------------------------- Server
const E_server = Promise.all([D_cfs, D_patches, D_webui, C_desk]).then(([cfs, pat, web, dk]) => impl('impl:server', 'Server', `Implement src/x32mcp/server.py + tests/integration/test_server_tools.py per DESIGN.md §19. The installed SDK is mcp 2.2.0: "from mcp.server.mcpserver import MCPServer, Context"; MCPServer(name, instructions=..., lifespan=<async context manager taking the server and yielding the App>); @server.tool() on async functions with typed params (defaults allowed; use "str | None = None"); return dicts (structured output auto-detected); @server.resource("x32://device") etc.; server.run("stdio"). Inspect the installed package (help(MCPServer), the tool manager) if anything is unclear — do NOT guess v1 FastMCP APIs. Build an App class (in server.py) that constructs Settings, Descriptor, EventBus, X32Connection, Policy, SnapshotStore, Desk, ReportStore, CfsManager, DashboardServer and exposes them; tools obtain it via a module-level "app" set in lifespan (so tools are plain async functions that tests can call directly with an App built on the fakedesk fixture — write a "make_app(fakedesk, tmp_path)" helper in the test). Implement EVERY tool in the §19 list with the exact names/signatures, the response envelope (ok/summary; errors {"ok": false, "error": {"code","message"}, "summary"}), the Tier-2 confirmation dance via policy.guard (first call → requires_confirmation + token; second call with token → execute; wrong/expired token → error), show_mode behaviour, and "not connected" errors (code NOT_CONNECTED) for anything needing the desk. Summaries are human sentences with dB and names ("Ch 5 'Vox Tony' fader −6.0 dB → −4.0 dB (ramped 300 ms)"). Tool docstrings are what the model sees: state units, ranges, tiers, and when to set force/confirm_token (never without the user asking). Add server "instructions" text summarising tiers, the confirmation dance, panic, and that the dashboard is read-only. main(): logging to stderr at settings.log_level, then server.run("stdio"). Lifespan: start dashboard if enabled (bind failure → warning), autoconnect if X32_HOST set (failure → warning), on exit stop cfs/dashboard/connection. Provide "python -m x32mcp.server" via src/x32mcp/__main__.py. Tests: build App on fakedesk; call each tool function: connection_status before/after connect; get_channel/get_bus/get_main/get_channel_sends/get_eq/get_dynamics envelope + units; set_fader/adjust_fader/mute/unmute/set_send/adjust_send/set_eq_band/set_pan/set_comp/set_gate/panic; set_main_fader dance (token round trip; wrong token error); recall_scene by index and by name (list_scenes + name match); save_scene dance; snapshot_desk/list_snapshots/diff_snapshot after a change (English string present)/restore_snapshot dance; show_mode(True) then recall_scene → SHOW_MODE_BLOCKS even with token; adjust_fader +4 in show mode → RELATIVE_TOO_LARGE; label_channel; apply_patch_plan/export_patch_plan with the example file; validate_ringout_eqs/setup_ringout_eqs dance/discover_mics/feedback_watch+feedback_watch_stop (with an injected synthetic source via App to keep it fast)/cfs_status/ring_out dance/list_ringout_reports; dashboard_status; a stdio smoke test: spawn "${PY} -m x32mcp.server" as a subprocess with env X32MCP_DASH=0 and use the mcp client library (mcp.client.stdio / ClientSession — inspect the installed package for the 2.x names) to initialize, list_tools (assert ≥ 40 tools and that "panic" and "recall_scene" are present), read resource x32://device, and call connection_status (expect ok false NOT_CONNECTED). Keep the whole test file < 90 s.${notes(cfs, pat, web, dk)}`))

// ---------------------------------------------------------------- Docs + Review
phase('Review')
const F_readme = E_server.then(s => impl('impl:readme', 'Review', `Write ${ROOT}/README.md and ${ROOT}/docs/GIG_CHECKLIST.md, and ${ROOT}/.mcp.json (Claude Code project config) — read the whole codebase first (src/x32mcp/*.py docstrings, device.yaml headers, tests) so the README is accurate. README sections: what it is (2 paragraphs, mention CFS²); architecture diagram (from BRIEF); requirements (Python 3.12 via uv on Windows — the exact commands used in this repo: uv installed via "powershell -ExecutionPolicy ByPass -c \\"irm https://astral.sh/uv/install.ps1 | iex\\"", "uv python install 3.12", "uv sync"); running the fake desk ("uv run x32-fakedesk --port 10023" / "python -m x32mcp.fakedesk"), the Maillot emulator note (docs/research/mcp_sdk.md + transport.md say what is known about it; link to his site; say we ship our own Python fake desk so nothing needs downloading), Claude Desktop config snippet (%APPDATA%\\Claude\\claude_desktop_config.json) with the real absolute paths for this machine: command "${ROOT}/.venv/Scripts/python.exe" args ["-m","x32mcp.server"] env {"X32_HOST": "<desk-ip>", "X32MCP_HOME": "${ROOT}"} — and the same as .mcp.json for Claude Code (type stdio); environment variables table (from config.py); tool reference grouped by phase/tier (generate from server.py docstrings — every tool, one line each, with tier); the safety model (tiers, clamps, confirmation dance example transcript, panic, snapshot-before-write, show mode); snapshots & diff; patch plans (link patches/README.md); CFS² section (how it works, the three levels, preflight, mic discovery, reports, what the dashboard shows, the non-goal: not a mid-set suppressor); dashboard (URL http://<pc-ip>:8032, ?demo=1, Windows firewall rule: "New-NetFirewallRule -DisplayName 'x32-mcp dashboard' -Direction Inbound -Protocol TCP -LocalPort 8032 -Action Allow" and the UDP note: the OSC socket binds an ephemeral UDP port; Windows will prompt on first run — allow on Private networks; or add an inbound UDP rule for python.exe restricted to the desk IP); Termux notes (from BRIEF §6a); development (running tests, layout, DESIGN.md, research docs); milestones status table (M1–M4, M6, M8 built and tested against the fake desk; M5/M7 require the real desk — link the manual checklists); operational notes (PSU cutouts → degraded handling, wall socket). GIG_CHECKLIST.md: pre-show, changeover, mid-set (emergency reflex = X32-Edit/physical, panic exists), post-show, plus the M5 and M7 manual verification protocols as tick lists. Return files + a short summary; tests_passed=true if "${PY}" -m pytest tests/test_targets_events_config.py passes (sanity only).${notes(s)}`))

const REVIEW_SCHEMA = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' }, line: { type: 'integer' }, severity: { type: 'string', enum: ['critical', 'major', 'minor'] },
          title: { type: 'string' }, detail: { type: 'string' }, fix: { type: 'string' },
        },
        required: ['file', 'line', 'severity', 'title', 'detail', 'fix'],
      },
    },
    summary: { type: 'string' },
  },
  required: ['findings', 'summary'],
}

const LENSES = [
  { key: 'protocol', prompt: `LENS: OSC protocol correctness. Verify against docs/research/*.md: single-socket send/receive (same port), /info & /xinfo arg order, /node request/reply matching and payload parsing incl. quoted strings and padded columns, fader taper formula and other scales vs research, mute inversion at every place /mix/on is read or written (grep for "mix/on" and check each), meter blob layout and RTA packing, /meters subscribe args + renew cadence, RTA source addresses, GEQ par index mapping and gain scale, insert/sel enum, scene addresses (/-action/goscene, /save arg order), typetag handling for messages without typetags, fakedesk fidelity vs research (it must emit the same formats the real desk does).` },
  { key: 'safety', prompt: `LENS: safety policy enforcement in CODE. For every write path in desk.py/cfs.py/provision.py/server.py verify: tier classification matches BRIEF §4 (phantom, main fader/mute, scene recall/save, routing, source, mute groups, inserts/fx type → Tier 2 with a confirmation token; token single-use + 60 s TTL + bound to the action); clamps (ch +5, bus 0, sends 0, EQ ±15, relative ±6 / ±3 in show mode, force semantics); show mode refuses scene recall/save even with a token; rate limiter on every Tier-1/2 write except panic; panic never blocked by anything (rate limit, show mode, degraded state check must not stop it from trying); snapshot-before-write happens exactly once per session before the first write; CFS² notch policy: cuts only, ≤ −9 dB per band, only the bus under test's GEQ, budget respected; ring-out master never above descriptor ceiling regardless of arguments; abort restores the starting master; nothing auto-unmutes a channel. Look for bypasses: any conn.set/send_raw call outside the policy path that writes a desk parameter.` },
  { key: 'robustness', prompt: `LENS: robustness & never-hang. Every awaited network operation has a timeout; tool calls cannot block > ~3 s; background tasks (heartbeat, watchdog, meters, detector, ramps, dashboard send loops) catch exceptions and log rather than die silently; task cancellation on close/stop; DEGRADED handling (writes refuse with a clear error, reads try once, reconnect backoff bounded); decode errors on inbound datagrams never crash the receive loop; blob replies never hit the text parser; no print() to stdout in src/x32mcp (grep); logging never writes to stdout; asyncio usage is correct under anyio (the MCP server runs the loop — no asyncio.run inside tools; no blocking sleeps; no thread-unsafe callbacks); Windows-specific paths/APIs absent; file I/O for snapshots/reports is atomic-ish (write temp then rename) and handles missing dirs; JSON serialisation handles -inf/NaN.` },
  { key: 'cfs-statemachine', prompt: `LENS: CFS² state machine & detector. Trace ring_out end-to-end in cfs.py: PREFLIGHT → SNAPSHOT → ARM → RAISE/HOLD/NOTCH/VERIFY loop → DONE/ABORT: check step/dwell timing, that gain raises stop while a candidate is being handled, decay verification logic, budget accounting vs NotchController, safety margin back-off, abort back-off, restore on connection loss (retry loop terminates), events emitted at each stage with useful data, report contents. Check feedback_watch arms only after preflight passes and validate_ringout_eqs refuses when insert is off/absent. Check the detector maths against DESIGN.md §12 (median excluding centre, slope units dB/s using real timestamps, cooldown, drift tolerance) and NotchController band selection (log-nearest) and merging. Check the fakedesk closed loop is not accidentally making tests pass for the wrong reason (e.g. ring decays regardless of which band was cut).` },
  { key: 'mcp-layer', prompt: `LENS: MCP layer & tool ergonomics. Verify server.py against the installed mcp 2.2.0 API (import it and introspect: tool registration, structured output, resources, lifespan, run('stdio')); every tool in DESIGN.md §19 exists with the exact name/params; parameter types are JSON-schema friendly (no Target objects, dict|None for plan is fine); docstrings state units/tiers and when to use force/confirm_token; responses always include ok + summary and never raw 0..1 floats (grep for suspicious floats); errors are envelopes not exceptions; the confirmation response shape matches BRIEF §4; resources read correctly; __main__ works; nothing writes to stdout; instructions text is accurate; the stdio smoke test exists and passes.` },
  { key: 'tests-integration', prompt: `LENS: test integrity. Run the FULL suite: "${PY}" -m pytest -q -p no:cacheprovider (from ${ROOT}) and report the exact result. For failures: diagnose the root cause (which module is wrong, not just which test) and give the precise fix. Also look for tests that pass vacuously (assert on nothing, swallowed exceptions, sleeps instead of awaiting conditions, mocks that hide integration breakage) and for flakiness risks (fixed ports, timing-tight assertions under load) — propose robust replacements. Check that the acceptance criteria in BRIEF §7 for M1, M2 (dump < 5 s, re-import), M3 (policy tests, ramps), M4 (recall needs confirmation, diff English), M6 (4 synthetic streams; notch writes), M8 (dashboard against synthetic streams) each have a test that actually exercises them; list any that are missing.` },
]

const G_reviews = Promise.all([E_server, F_readme]).then(([s, r]) => parallel(LENSES.map(l => () => agent(`${COMMON}

You are a REVIEWER, not an implementer: do NOT modify any file. Read the codebase under ${ROOT}/src/x32mcp, device.yaml, tests/, docs/DESIGN.md, docs/BRIEF.md and docs/research/*.md. You may run tests and small Python snippets (use "${PY}").
${l.prompt}
Assume there are real defects and hunt for them; verify each suspected defect by reading the actual code path (and running it where practical) before reporting — no speculative findings. Report each finding with file, 1-based line, severity, a one-line title, the concrete failure scenario, and the exact fix. Return structured output only.`, { label: `review:${l.key}`, phase: 'Review', schema: REVIEW_SCHEMA, effort: 'high' }))))

// Barrier is justified here: fixes must be deduplicated across lenses and grouped by file so fixers don't collide.
const reviews = (await G_reviews).filter(Boolean)
const all = reviews.flatMap(r => r.findings)
const seen = new Set()
const uniq = all.filter(f => { const k = `${f.file}:${f.title.toLowerCase().slice(0, 40)}`; if (seen.has(k)) return false; seen.add(k); return true })
log(`review: ${all.length} findings, ${uniq.length} unique (${uniq.filter(f => f.severity === 'critical').length} critical, ${uniq.filter(f => f.severity === 'major').length} major)`)

// Group by primary file cluster so each fixer owns disjoint files.
const CLUSTERS = [
  { key: 'protocol', files: ['osc.py', 'scales.py', 'connection.py', 'nodes.py', 'meters.py', 'fakedesk.py', 'device.yaml', 'descriptor.py'] },
  { key: 'policy-desk', files: ['policy.py', 'desk.py', 'patches.py', 'targets.py', 'events.py', 'config.py'] },
  { key: 'cfs', files: ['detector.py', 'cfs.py', 'provision.py'] },
  { key: 'server-web', files: ['server.py', '__main__.py', 'webui.py', 'index.html', 'README.md', 'GIG_CHECKLIST.md', '.mcp.json'] },
]
const clusterOf = f => CLUSTERS.find(c => c.files.some(n => f.file.replace(/\\/g, '/').endsWith('/' + n) || f.file.endsWith(n))) || CLUSTERS[3]
const groups = CLUSTERS.map(c => ({ c, findings: uniq.filter(f => clusterOf(f) === c) })).filter(g => g.findings.length)

const FIX_SCHEMA = { type: 'object', properties: { fixed: { type: 'array', items: { type: 'string' } }, skipped: { type: 'array', items: { type: 'string' } }, test_summary: { type: 'string' } }, required: ['fixed', 'skipped', 'test_summary'] }

const fixes = await parallel(groups.map(g => () => agent(`${COMMON}

You are a FIXER for the "${g.c.key}" cluster. You may edit ONLY these files (plus their tests under tests/): ${g.c.files.join(', ')} under ${ROOT}/src/x32mcp (device.yaml at repo root; index.html under webui/; README/GIG_CHECKLIST under root/docs). Apply each finding below unless, after reading the code, you are certain it is wrong (then list it in skipped with the reason). Keep DESIGN.md signatures. After fixing, run the tests for the modules you touched AND "${PY}" -m pytest tests -q -x --timeout=120 -p no:cacheprovider for the whole suite (other fixers are working on other files concurrently — if a failure is clearly in another cluster's file, report it in skipped rather than editing it).

FINDINGS:
${g.findings.map((f, i) => `${i + 1}. [${f.severity}] ${f.file}:${f.line} — ${f.title}\n   ${f.detail}\n   FIX: ${f.fix}`).join('\n')}`, { label: `fix:${g.c.key}`, phase: 'Review', schema: FIX_SCHEMA })))

const final = await agent(`${COMMON}

FINAL INTEGRATION PASS. Run the full suite: "${PY}" -m pytest tests -q --timeout=180 -p no:cacheprovider (from ${ROOT}). If anything fails, fix it (you may edit any file; keep DESIGN.md signatures; prefer fixing the module over weakening the test) and re-run until green or until you are certain a failure needs a design decision (then report it). Then run "${PY}" -m x32mcp.server --help 2>&1 | head -5 (it may just start and wait on stdin — kill it after 3 s; the point is that it imports and starts without stdout noise) and "${PY}" -c "import x32mcp.server" to confirm a clean import. Report: final pytest tail, number of tests, any remaining failures with root cause, and a list of files changed.`, { label: 'final:integrate', phase: 'Review', schema: { type: 'object', properties: { pytest_tail: { type: 'string' }, tests_total: { type: 'integer' }, all_green: { type: 'boolean' }, remaining_failures: { type: 'array', items: { type: 'string' } }, files_changed: { type: 'array', items: { type: 'string' } } }, required: ['pytest_tail', 'tests_total', 'all_green', 'remaining_failures', 'files_changed'] } })

return {
  modules: { osc: await A_osc, scales: await A_scales, yaml: await A_yaml, page: await A_page, descriptor: await A_desc, connection: await B_conn, nodes: await B_nodes, policy: await B_policy, meters: await B_meters, detector: await B_detector, fakedesk: await C_fakedesk, desk: await C_desk, cfs: await D_cfs, patches: await D_patches, webui: await D_webui, server: await E_server, readme: await F_readme },
  review: { total: all.length, unique: uniq.length, findings: uniq },
  fixes,
  final,
}
